    <title>Cat Care FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f6f7fb;
        --surface: #ffffff;
        --surface-strong: #eef2ff;
        --text: #172033;
        --muted: #5f6f89;
        --accent: #635bff;
        --accent-dark: #4a43d1;
        --border: #dfe5f2;
