          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (max-width: 620px) {
        .page-shell {
          width: min(100% - 24px, 980px);
          padding: 38px 0;
        }

        .faq-card {
          border-radius: 24px;
        }

        .faq-trigger {
          padding: 18px;
        }

        .details {
          padding: 0 18px 20px;
        }
      }
    </style>
  </head>
  <body>
    <main class="page-shell" id="app"></main>

    <script>
      const faqs = [
        {
          question: "How often should I feed my cat?",
          answer:
            "Most adult cats do well with two measured meals per day, while kittens usually need three or more smaller meals. Your veterinarian can help choose portions based on age, weight, activity level, and health needs."
        },
        {
          question: "Why does my cat knead blankets or laps?",
          answer:
            "Kneading is a comforting behavior cats often learn as kittens. Adult cats may knead when they feel relaxed, secure, or affectionate, especially on soft surfaces that remind them of nursing."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Indoor cats benefit from daily play, scratching posts, window perches, puzzle feeders, and safe places to climb or hide. Enrichment supports healthy exercise and reduces boredom-related stress."
        },
        {
          question: "How can I tell if my cat is stressed?",
          answer:
            "Common signs include hiding more than usual, appetite changes, over-grooming, litter box changes, flattened ears, tail twitching, or sudden aggression. Persistent changes should be discussed with a veterinarian."
        },
        {
          question: "How often should I clean the litter box?",
          answer:
            "Scoop at least once daily and fully refresh the box on a regular schedule based on the litter type. A clean box encourages consistent use and makes it easier to spot health changes."
        },
        {
          question: "Should cats visit the veterinarian every year?",
          answer:
            "Annual wellness visits are recommended for most cats, even if they seem healthy. Regular exams can catch dental disease, weight changes, kidney issues, and other concerns before they become harder to treat."
        }
      ];

      function FaqItem({ question, answer }, index) {
        const panelId = `faq-panel-${index + 1}`;
        const buttonId = `faq-button-${index + 1}`;

        return `
          <div class="example">
            <h2>
              <button
                class="faq-trigger"
                id="${buttonId}"
                type="button"
                aria-expanded="false"
                aria-controls="${panelId}"
              >
                <span>${question}</span>
                <span class="icon" aria-hidden="true"></span>
              </button>
            </h2>
            <div
              class="details"
              id="${panelId}"
              role="region"
              aria-labelledby="${buttonId}"
              hidden
            >
              <p>${answer}</p>
            </div>
          </div>
        `;
      }

      function FaqPage() {
        return `
          <section class="hero" aria-labelledby="page-title">
            <p class="eyebrow">Cat care guide</p>
            <h1 id="page-title">Frequently asked questions about cats</h1>
            <p class="intro">
              Practical answers for new and experienced cat people, from feeding
              routines to enrichment, stress signals, litter care, and wellness.
            </p>
          </section>

          <section class="faq-card" aria-label="Cat frequently asked questions">
            ${faqs.map(FaqItem).join("")}
          </section>

          <p class="footer-note">
            For sudden behavior changes, pain, or appetite loss, contact a veterinarian.
          </p>
        `;
      }

      document.getElementById("app").innerHTML = FaqPage();

      document.querySelectorAll(".faq-trigger").forEach((button) => {
        button.addEventListener("click", () => {
          const panel = document.getElementById(button.getAttribute("aria-controls"));
          const isExpanded = button.getAttribute("aria-expanded") === "true";

          button.setAttribute("aria-expanded", String(!isExpanded));
          panel.hidden = isExpanded;
        });
      });
    </script>
  </body>
</html>
