        },
        {
          question: "Should cats visit the veterinarian every year?",
          answer:
            "Annual wellness visits are recommended for most cats, even if they seem healthy. Regular exams can catch dental disease, weight changes, kidney issues, and other concerns before they become harder to treat."
        }
      ];

      function FaqItem({ question, answer }, index) {
        const panelId = `faq-panel-${index + 1}`;
        const buttonId = `faq-button-${index + 1}`;

        return `
